-- C-155: 21 high-travel holiday destinations (Zaid, 16 Oct: "at least 400-500 five-star hotels,
-- prioritise high travel places") and their 159 best five-star hotels. Picked from
-- scripts/catalog/candidates.json (LiteAPI five-star within the destination's area, matched to
-- Tripadvisor by name and ≤ 250 m), ranked by Tripadvisor's typical minimum price among hotels
-- with ≥ 200 reviews and a rating ≥ 4.3. Every hotel returned live prices from Xotelo on at least
-- one of six test dates across the season (14 that never did were left out, e.g. Cheval Blanc
-- St-Tropez, J.K. Place Capri); Fairmont Monte-Carlo left out (four stars). Photos are the hotels'
-- own via LiteAPI (D-51), checked by eye, self-hosted in apps/web/public/hotels. Google Hotels ids
-- come later, on demand (C-153). Idempotent.

insert into public.cities (slug, name_de, name_en, country_code)
values
  ('mallorca', 'Mallorca', 'Mallorca', 'ES'),
  ('ibiza', 'Ibiza', 'Ibiza', 'ES'),
  ('cote-d-azur', 'Côte d’Azur', 'French Riviera', 'FR'),
  ('monaco', 'Monaco', 'Monaco', 'MC'),
  ('santorini', 'Santorini', 'Santorini', 'GR'),
  ('mykonos', 'Mykonos', 'Mykonos', 'GR'),
  ('amalfikueste', 'Amalfiküste', 'Amalfi Coast', 'IT'),
  ('capri', 'Capri', 'Capri', 'IT'),
  ('venedig', 'Venedig', 'Venice', 'IT'),
  ('florenz', 'Florenz', 'Florence', 'IT'),
  ('prag', 'Prag', 'Prague', 'CZ'),
  ('budapest', 'Budapest', 'Budapest', 'HU'),
  ('zermatt', 'Zermatt', 'Zermatt', 'CH'),
  ('marrakesch', 'Marrakesch', 'Marrakech', 'MA'),
  ('bali', 'Bali', 'Bali', 'ID'),
  ('phuket', 'Phuket', 'Phuket', 'TH'),
  ('doha', 'Doha', 'Doha', 'QA'),
  ('mauritius', 'Mauritius', 'Mauritius', 'MU'),
  ('seychellen', 'Seychellen', 'Seychelles', 'SC'),
  ('kapstadt', 'Kapstadt', 'Cape Town', 'ZA'),
  ('riviera-maya', 'Cancún & Riviera Maya', 'Cancún & Riviera Maya', 'MX')
on conflict (slug) do nothing;

insert into public.hotels
  (slug, name, city_id, lat, lng, xotelo_key, liteapi_id, image_url, image_credit,
   image_source_url, active)
select v.slug, v.name, c.id, v.lat, v.lng, v.xotelo_key,
       case when exists (select 1 from public.hotels h where h.liteapi_id = v.liteapi_id)
            then null else v.liteapi_id end,
       v.image_url, v.image_credit, v.image_source_url, true
